<script setup lang="ts">
import {ref} from 'vue';import type {RequestFn} from './media';
const props=defineProps<{request:RequestFn,path:string,method:'DELETE'|'POST',payload?:Record<string,any>,title:string,message:string,buttonText?:string}>();const emit=defineEmits<{close:[],changed:[message:string]}>();const busy=ref(false),confirmed=ref(false),error=ref('');
async function submit(){if(busy.value||!confirmed.value)return;busy.value=true;error.value='';try{const r=await props.request(props.path,props.method,{...props.payload,confirmed:true});emit('changed',r.message||'已完成')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
</script>
<template><div class="modal-backdrop" @click.self="!busy&&emit('close')"><form class="modal" role="dialog" aria-modal="true" :aria-label="title" @submit.prevent="submit"><div class="section-head"><h2>{{title}}</h2><button type="button" :disabled="busy" @click="emit('close')" aria-label="关闭">×</button></div><div v-if="error" class="alert error" role="alert">{{error}}</div><p class="pre">{{message}}</p><label class="multi"><input type="checkbox" v-model="confirmed">我已核对并确认此操作</label><div class="modal-actions"><button type="button" :disabled="busy" @click="emit('close')">取消</button><button class="primary" :disabled="busy||!confirmed">{{buttonText||'确认'}}</button></div></form></div></template>
